// Cek tiap nomor ke WAHA check-exists, balas {registered, not_registered}.
// Sinkron: hasil dikembalikan via Respond to Webhook.

const body = ($input.first().json.body) || $input.first().json;
const targets = Array.isArray(body.targets) ? body.targets : [];

const base = ($env.N8N_WAHA_BASE_URL || 'http://waha:3000').replace(/\/+$/, '');
const apiKey = $env.N8N_WAHA_API_KEY || '';
const session = $env.N8N_WAHA_SESSION || 'default';

const registered = [];
const not_registered = [];

for (const num of targets) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/api/contacts/check-exists',
      headers: { 'X-Api-Key': apiKey },
      qs: { phone: String(num), session },
      json: true,
    });
    if (res && res.numberExists) registered.push(num);
    else not_registered.push(num);
  } catch (e) {
    // gagal cek -> biarkan unknown (tidak masuk kedua list)
  }
}

return [{ json: { status: true, registered, not_registered } }];
